// Helper to create synthetic ImageData frames
function createSyntheticFrame(
faces,
frameW = 640,
frameH = 360)
{
  const data = new Uint8ClampedArray(frameW * frameH * 4);

  // Background: slate navy wall (non-skin)
  for (let i = 0; i < frameW * frameH; i++) {
    data[i * 4] = 15; // R
    data[i * 4 + 1] = 23; // G
    data[i * 4 + 2] = 42; // B
    data[i * 4 + 3] = 255;
  }

  // Draw each face with skin chromaticity
  for (const f of faces) {
    const lumFactor = f.luminance ?? 1.0;
    const skinR = Math.min(240, Math.floor(180 * lumFactor));
    const skinG = Math.min(220, Math.floor(130 * lumFactor));
    const skinB = Math.min(200, Math.floor(100 * lumFactor));

    for (let y = f.y; y < f.y + f.h && y < frameH; y++) {
      for (let x = f.x; x < f.x + f.w && x < frameW; x++) {
        // Oval face mask
        const cx = f.x + f.w / 2;
        const cy = f.y + f.h / 2;
        const rx = f.w / 2;
        const ry = f.h / 2;
        const dx = (x - cx) / rx;
        const dy = (y - cy) / ry;

        if (dx * dx + dy * dy <= 1.0) {
          const idx = (y * frameW + x) * 4;
          data[idx] = skinR;
          data[idx + 1] = skinG;
          data[idx + 2] = skinB;
          data[idx + 3] = 255;
        }
      }
    }
  }

  return {
    width: frameW,
    height: frameH,
    data,
    colorSpace: 'srgb'
  };
}

